    "content": "金秋十月，举国同庆。漫步多地繁华商圈、城市地铁，只见巨幅广告屏上，轮番播放的不是常见的带货明星、产品广告，而是把黄金广告位留给了钱学森、邓稼先、屠呦呦、袁隆平等一批功勋科学家。 车水马龙的假日，国士肖像与励志箴言，吸引无数游客驻足凝望、拍照打卡。话题“商圈大屏致敬科学家”刷屏网络，一句“这才是我们最该追的星”，道出了无数人的心声。 大国气象，既要烟火气息的商业活力，更需坚实厚重的精神底气。国庆之际，这些民族脊梁走上广告C位，让科学家精神浸润滋养我们的心灵，成为这个国庆的一道靓丽风景。 今年六月，山东菏泽单县银座商城…"
