    "description": "新华社北京10月3日电（记者倪远诗）红十字会与红新月会国际联合会非洲区域办公室副主任皮埃尔·克雷默和驻非盟及国际组织代表阿莎·穆罕默德日前在接受新华社记者采访时表示，中国在减贫和社区发展等方面的经验，可为非洲韧性社区建设提供重要借鉴。 9月10日，为期两周的“中非合作框架下红十字红新月韧性社区建设研修班”在北京开班。作为中国对外援助人力资源开发合作项目，该研修班由中国红十字会训练中心承办、红十字会与红新月会国际联合会提供支持，来自19个…",
    "content": "新华社北京10月3日电（记者倪远诗）红十字会与红新月会国际联合会非洲区域办公室副主任皮埃尔·克雷默和驻非盟及国际组织代表阿莎·穆罕默德日前在接受新华社记者采访时表示，中国在减贫和社区发展等方面的经验，可为非洲韧性社区建设提供重要借鉴。 9月10日，为期两周的“中非合作框架下红十字红新月韧性社区建设研修班”在北京开班。作为中国对外援助人力资源开发合作项目，该研修班由中国红十字会训练中心承办、红十字会与红新月会国际联合会提供支持，来自19个非洲国家红十字会和红新月会及红十字会与红新月会国际联合会的26名代表参加。 “此…"
