    "description": "2026年10月03日 本报记者 乔 栋摄 \"> 青海果洛藏族自治州班玛县，是红军长征途经地。在班玛县马格勒村，合作社的牦牛正不紧不慢，向着低海拔的冬季牧场转移。 村党支部副书记依尼，在手机上收到一笔转账——合作社结算的收购款，“我们家的牦牛皮，卖的价钱不赖！” 牛皮，也曾是红军的救命“口粮”。90年前，红军在班玛县周边扎营时，地里豆荚饱满。当地老人回忆：“哪怕挖野菜、捡牛羊骨头，用牛皮带煮汤喝，也没有一个红军战士跑进地里摘豆荚。”这种…",
    "content": "2026年10月03日 班玛县牧民在挤牦牛奶。 本报记者 乔 栋摄 \"> 青海果洛藏族自治州班玛县，是红军长征途经地。在班玛县马格勒村，合作社的牦牛正不紧不慢，向着低海拔的冬季牧场转移。 村党支部副书记依尼，在手机上收到一笔转账——合作社结算的收购款，“我们家的牦牛皮，卖的价钱不赖！” 牛皮，也曾是红军的救命“口粮”。90年前，红军在班玛县周边扎营时，地里豆荚饱满。当地老人回忆：“哪怕挖野菜、捡牛羊骨头，用牛皮带煮汤喝，也没有一个红军战士跑进地里摘豆荚。”这种顾全大局、严守纪律的精神，让当地群众深受触动，感念至今。…"
