    "description": "2026年10月03日 10月1日，澳门特区政府庆祝中华人民共和国成立77周年升旗仪式上，首次全面采用中式队列步操及中国人民解放军敬礼方式。护旗队及仪仗队以饱满的热忱、昂扬的风貌，展现专业风采与飒爽英姿，用铿锵的步伐向祖国献礼。 澳门特区政府不久前修订《敬礼及礼仪规章》行政法规，规定澳门保安部队及保安部门人员的敬礼及礼仪制度以中国人民解放军的敬礼方式及中式步操作为标准。修改后的行政法规自10月1日起生效。 澳门全面推行中式队列步操，正式…",
    "content": "2026年10月03日 10月1日，澳门特区政府庆祝中华人民共和国成立77周年升旗仪式上，首次全面采用中式队列步操及中国人民解放军敬礼方式。护旗队及仪仗队以饱满的热忱、昂扬的风貌，展现专业风采与飒爽英姿，用铿锵的步伐向祖国献礼。 澳门特区政府不久前修订《敬礼及礼仪规章》行政法规，规定澳门保安部队及保安部门人员的敬礼及礼仪制度以中国人民解放军的敬礼方式及中式步操作为标准。修改后的行政法规自10月1日起生效。 澳门全面推行中式队列步操，正式与国家标准接轨，彰显了国家主权与民族精神。整齐划一的正步，表达了澳门儿女对祖国的…"
