    "description": "2026年10月03日 耿车蝶变，是一个普通乡村成功践行“两山”理念的生动样本。 40多年前，耿车人大力发展废旧塑料回收加工产业，创造了蜚声全国的“耿车模式”。然而，在经济利益的驱动下，长期低端粗放的发展带来了严重的环境问题，2012年耿车被当时的环境保护部列为全国八大重点环境整治区域。耿车在向金山银山的狂奔中迷失了方向，失去了绿水青山，走进了发展的“死胡同”。 进入新时代，习近平生态文明思想特别是“两山”理念，为饱尝生态之殇的耿车人指…",
