    "description": "2026年10月03日 临漳县文化广电和旅游局供图 \"> 宋龙雨摄 \"> 《赤壁》 杜 牧（唐） 折戟沉沙铁未销，自将磨洗认前朝。 东风不与周郎便，铜雀春深锁二乔。 晚唐诗人杜牧凭一句“铜雀春深锁二乔”，让铜雀台的名字流传千古。很多人却未必知晓，诗中反复咏叹的铜雀台，遗址就坐落于今天临漳县的邺城国家考古遗址公园内。 历史的烟云曾在邺城层层交叠。春秋时期，齐桓公始筑邺城；建安年间，曹操于旧基上重新规划营建了邺北城，后将其作为魏国王都；东魏…",
    "content": "2026年10月03日 铜雀三台示意图（从左向右依次为金凤台、铜雀台、冰井台）。 临漳县文化广电和旅游局供图 \"> 邺城博物馆外景。 宋龙雨摄 \"> 《赤壁》 杜&nbsp;&nbsp;牧（唐） 折戟沉沙铁未销，自将磨洗认前朝。 东风不与周郎便，铜雀春深锁二乔。 晚唐诗人杜牧凭一句“铜雀春深锁二乔”，让铜雀台的名字流传千古。很多人却未必知晓，诗中反复咏叹的铜雀台，遗址就坐落于今天临漳县的邺城国家考古遗址公园内。 历史的烟云曾在邺城层层交叠。春秋时期，齐桓公始筑邺城；建安年间，曹操于旧基上重新规划营建了邺北城，后将其…"
