    "description": "2026年10月03日 走进中国古典宫殿、寺院、园林与民居，常会看到一种依附主屋、向外凸出的附属空间，这便是传统建筑中颇具特色的抱厦（见图，山西省古建筑与彩塑壁画保护研究院供图）。它紧贴主体建筑一面或多面而建，因平面多呈“凸”字形，古称“龟头屋”。 抱厦依主体而建，位置不同，功用与规格各异。最常见的是设于正前方中轴线上，用以突显主入口、强化仪式感；背面的倒座抱厦，则多为仓储、居所等辅助空间。规格最高的当数十字抱厦，主殿四面各出一厦，形成…",
    "content": "2026年10月03日 走进中国古典宫殿、寺院、园林与民居，常会看到一种依附主屋、向外凸出的附属空间，这便是传统建筑中颇具特色的抱厦（见图，山西省古建筑与彩塑壁画保护研究院供图）。它紧贴主体建筑一面或多面而建，因平面多呈“凸”字形，古称“龟头屋”。 抱厦依主体而建，位置不同，功用与规格各异。最常见的是设于正前方中轴线上，用以突显主入口、强化仪式感；背面的倒座抱厦，则多为仓储、居所等辅助空间。规格最高的当数十字抱厦，主殿四面各出一厦，形成十字平面，多用于宫殿、寺院等高等级建筑。河北正定隆兴寺摩尼殿，便是北宋十字抱厦留…"
