    "description": "2026年10月03日 琵琶行（节选） 白居易（唐） 低眉信手续续弹，说尽心中无限事。 轻拢慢捻抹复挑，初为霓裳后六幺。 大弦嘈嘈如急雨，小弦切切如私语。 嘈嘈切切错杂弹，大珠小珠落玉盘。 暮色渐起，登临琵琶亭，长江东流而去，水天相接处明月初升，清辉铺洒江面，漾起粼粼波光。 “九派浔阳郡，分明似画图。”九江，古称浔阳、江州，自古便是文人墨客流连之地。唐代诗人白居易曾在此谪居3年多，留下370多篇诗文，其中，《琵琶行》更是成为传诵千古的文…",
    "content": "2026年10月03日 琵琶行（节选） 白居易（唐） 低眉信手续续弹，说尽心中无限事。 轻拢慢捻抹复挑，初为霓裳后六幺。 大弦嘈嘈如急雨，小弦切切如私语。 嘈嘈切切错杂弹，大珠小珠落玉盘。 暮色渐起，登临琵琶亭，长江东流而去，水天相接处明月初升，清辉铺洒江面，漾起粼粼波光。 “九派浔阳郡，分明似画图。”九江，古称浔阳、江州，自古便是文人墨客流连之地。唐代诗人白居易曾在此谪居3年多，留下370多篇诗文，其中，《琵琶行》更是成为传诵千古的文学绝唱。 唐代元和十年（公元815年），白居易被贬至江州任司马。翌年秋夜，他在浔…"
