    "description": "2026年10月03日 郭 扬摄 \"> 前不久，浙江杭州举办了一场特殊的开学典礼——首批30名“机器人学生”报到入学，它们来自工业、服务、安保等不同领域，“家长”中既有中小企业代表，也有相关部门单位。 这是由浙江大学机器人研究院联合浙江省质量科学研究院及行业头部企业共同打造的“杭州机器人学校”。在这里，机器人将接受系统化“职业技能”培训，学习各种场景中的应用技能，考取“技能证书”后走向工作岗位，实现从“科技玩具”到“实用工具”的蜕变。 …",
    "content": "2026年10月03日 杭州机器人学校工作人员在对机器狗进行标准化训练。 郭 扬摄 \"> 前不久，浙江杭州举办了一场特殊的开学典礼——首批30名“机器人学生”报到入学，它们来自工业、服务、安保等不同领域，“家长”中既有中小企业代表，也有相关部门单位。 这是由浙江大学机器人研究院联合浙江省质量科学研究院及行业头部企业共同打造的“杭州机器人学校”。在这里，机器人将接受系统化“职业技能”培训，学习各种场景中的应用技能，考取“技能证书”后走向工作岗位，实现从“科技玩具”到“实用工具”的蜕变。 先说入学条件，浙江大学机器人研…"
