    "author": "",
    "description": "2026年10月03日 中国国家博物馆供图 \"> “中国大宁，子孙益昌。黄常（裳）元吉，有纪刚（纲）。” 这是收藏于中国国家博物馆（以下简称“国博”）一面西汉四神博局纹鎏金铜镜（以下简称“中国大宁镜”）上的部分铭文。“中国大宁，子孙益昌”一句，说出了从古至今华夏儿女的共同心愿。 1951—1952年，它被发现于湖南长沙城北的伍家岭211号西汉墓，1959年调拨至中国历史博物馆（国博前身）。 这面鎏金铜镜，有着怎样的传奇故事？ 根据镜背纹…",
    "content": "2026年10月03日 西汉“中国大宁”四神博局纹鎏金铜镜（右图为该镜拓本）。 中国国家博物馆供图 \"> “中国大宁，子孙益昌。黄常（裳）元吉，有纪刚（纲）。” 这是收藏于中国国家博物馆（以下简称“国博”）一面西汉四神博局纹鎏金铜镜（以下简称“中国大宁镜”）上的部分铭文。“中国大宁，子孙益昌”一句，说出了从古至今华夏儿女的共同心愿。 1951—1952年，它被发现于湖南长沙城北的伍家岭211号西汉墓，1959年调拨至中国历史博物馆（国博前身）。 这面鎏金铜镜，有着怎样的传奇故事？ 根据镜背纹饰与设计风格，中国大宁镜…"
