    "title": "08版 - 逨盘揭示家国一体文明基因（大地风华）",
    "link": "http://paper.people.com.cn/rmrb/pc/content/202610/03/content_30184151.html",
    "pub_date": "2026-10-03 08:26:02",
    "author": "",
    "description": "2026年10月03日 宝鸡青铜器博物院供图 \"> 青铜不语，铭文作史。 在宝鸡青铜器博物院，逨盘静卧于展柜之中，光泽温润，恍若初铸之时。古人称青铜为“吉金”，吉金初成，灿若黄金，是礼敬天地、昭告先祖的神圣之色。3000年岁月流转，它不曾褪去这份庄严。 3000年前，它曾盛水盥洗，是宗庙祭祀中的礼器。3000年后，当考古工作者轻轻拂去黄土，它腹底那370余字铭文重见天日。器主单逨，以盘为纸，书写了一个家族八代人的忠诚，也书写了一个王朝1…",
    "content": "2026年10月03日 宝鸡青铜器博物院藏西周逨盘。 宝鸡青铜器博物院供图 \"> 青铜不语，铭文作史。 在宝鸡青铜器博物院，逨盘静卧于展柜之中，光泽温润，恍若初铸之时。古人称青铜为“吉金”，吉金初成，灿若黄金，是礼敬天地、昭告先祖的神圣之色。3000年岁月流转，它不曾褪去这份庄严。 3000年前，它曾盛水盥洗，是宗庙祭祀中的礼器。3000年后，当考古工作者轻轻拂去黄土，它腹底那370余字铭文重见天日。器主单逨，以盘为纸，书写了一个家族八代人的忠诚，也书写了一个王朝12位王的兴替历程。 这件青铜器铸于西周宣王时期，2…"
