    "content": "2026年10月03日 国家图书馆藏《永乐大典》杭字册。 谢冬荣供图 \"> 《永乐大典》是国家图书馆重要的收藏之一。“盛世修典”，大型典籍对文脉传承的意义，不言而喻。《永乐大典》尤为特殊——它不仅是我国古代最大的一部类书，编排方式也最特别；其坎坷的命运，更令人感慨。 一般类书，都是按内容类别编排，《永乐大典》却采用“用韵以统字，用字以系事”的方法：先按《洪武正韵》收录的单字排序，再把各书中与这个字相关的内容广泛辑录下来，整句、整段甚至整本书抄录，系在该字之下。 它的内容极其丰富，堪称一部包罗万象的百科全书。刚开始编…"
