    "description": "最近，“闪身步”和“狗熊哆嗦毛”成了全网最火爆的“形象动作”。 啥是“闪身步”和“狗熊哆嗦毛”？媒体报道描述得很形象：一个人腰一拧、肩一错，“嗖”的一下人就飘出去了，动作像凌波微步，这是“闪身步”；一个人面无表情地站着，突然大喊一声“狗熊哆嗦毛”，嘴里叨咕着“隆咚哐隆咚哐”，全身开始不受控制地抽搐起来，就像“狗熊踩了电门”，这是“狗熊哆嗦毛”。 △明文军老师教学视频 这两个动作不仅在线上火，在线下也迅速蔓延。国庆期间，在江苏某古镇表演场…",
    "content": "最近，“闪身步”和“狗熊哆嗦毛”成了全网最火爆的“形象动作”。 啥是“闪身步”和“狗熊哆嗦毛”？媒体报道描述得很形象：一个人腰一拧、肩一错，“嗖”的一下人就飘出去了，动作像凌波微步，这是“闪身步”；一个人面无表情地站着，突然大喊一声“狗熊哆嗦毛”，嘴里叨咕着“隆咚哐隆咚哐”，全身开始不受控制地抽搐起来，就像“狗熊踩了电门”，这是“狗熊哆嗦毛”。 △明文军老师教学视频 这两个动作不仅在线上火，在线下也迅速蔓延。国庆期间，在江苏某古镇表演场所，表演者向观众展示了把“闪身步”和“狗熊哆嗦毛”变成“组合拳”的新技能，孩子们…"
