    "description": "1950年10月3日，新中国第一所新型正规大学，中国人民大学在北京正式成立，吴玉章为第一任校长。它是在陕北公学、华北联合大学、北方大学和华北大学的基础上建立。",
    "content": "1950年10月3日，新中国第一所新型正规大学，中国人民大学在北京正式成立，吴玉章为第一任校长。它是在陕北公学、华北联合大学、北方大学和华北大学的基础上建立。"
