    "description": "【编者按】 县城，盛得下梦想，载得动乡愁。一到假期，年轻人“奔县”成风潮。今年国庆，澎湃新闻记者奔赴“县”场，感受中国县域的生机、韧性与真实生活。 这里既有县域产业突围、文旅融合的鲜活探索，也有古老文脉在小城焕发新生的转型实践。在一个个县域样本中，发现一个别样精彩的中国。 国庆假期是观察县域经济活力与特色的重要节点，澎湃新闻再推策划《奔赴“县”场》，读懂中国经济发展的深层动力。 今天，我们关注四川平昌。 海报设计：祝碧晨 城之变 国庆前…",
