    "content": "在2026抖音创作者大会，记者见到了短视频创作者蓝战非。 2023年起，蓝战非开启环球旅行系列。他游历了湘西、张家界、拉萨等地，随后走向世界，足迹遍布南极、非洲、美洲、欧洲等地。 他以记录真实、接地气的旅行体验，传递出独特的个人风格与生活态度。跟随记者的镜头，一起走进他的故事。 记者：沙青、赵小帅、孙彪、孙敏 新华社音视频部制作"
