    "content": "在物理诺奖即将揭晓之际，“诺奖风向标”沃尔夫物理学奖10月1日颁给了德国物理学家、马克斯·普朗克量子光学研究所和慕尼黑大学教授Immanuel F. Bloch，以及中国科学院外籍院士、美国国家标准与技术研究院教授叶军，表彰他们在超冷原子系统调控领域，取得了变革性且具广泛适用性的突破。 今年9月，中国科学院院士、南方科技大学校长薛其坤，因“对量子反常霍尔效应的实验观测”，入选素有“诺奖风向标”之称的“引文桂冠奖”。 2026年诺贝尔物理学奖最早将于10月6日欧洲中部夏令时间11时45分在瑞典皇家科学院公布。今年物理…"
