    "description": "2021年政权更迭后，阿富汗一度成为中国商人口耳相传的“淘金热土”，宝石商人和矿业从业者进入这个内陆国家寻找矿点和采购设备，试图从升温的矿业开采领域分一杯羹。 “人越来越多。2025年砂金淘金热达到顶峰时，涌入阿富汗的中国商人迅速膨胀至近万人规模。”2022年到阿富汗经商的郑瑢告诉澎湃新闻（www.thepaper.cn）。 这场“淘金热”来得迅猛，退潮同样突然。2026年后，随着早期商机逐渐消退，经营成本与安全风险不断显现，大量中国商…",
    "content": "2021年政权更迭后，阿富汗一度成为中国商人口耳相传的“淘金热土”，宝石商人和矿业从业者进入这个内陆国家寻找矿点和采购设备，试图从升温的矿业开采领域分一杯羹。 “人越来越多。2025年砂金淘金热达到顶峰时，涌入阿富汗的中国商人迅速膨胀至近万人规模。”2022年到阿富汗经商的郑瑢告诉澎湃新闻（www.thepaper.cn）。 这场“淘金热”来得迅猛，退潮同样突然。2026年后，随着早期商机逐渐消退，经营成本与安全风险不断显现，大量中国商人陆续离开。根据郑瑢的估算，目前常驻阿富汗的中国商人可能已不足两千。 当地时间2…"
