    "author": "王泽宇,李军",
    "description": "新华社巴格达10月2日电（记者王泽宇 李军）伊拉克总理新闻办公室2日发布声明说，经与美国方面沟通后达成协议，允许伊朗各航空公司每日运营总计40架次往返伊拉克纳杰夫国际机场的航班，但伊朗马汉航空被除外。 声明说，该协议旨在便利伊拉克与伊朗两地人员往来，重点满足医疗、宗教朝圣、旅游、教育等方面出行需求。 美国财政部9月8日发布公告，把27家伊朗航空公司及其他多个公司列入“特别指定国民清单”以实施制裁。受美国制裁影响，伊拉克多个机场暂停所有往…",
