    "content": "新华社纽约10月2日电 纽约股市三大股指2日上涨。 截至当天收盘，道琼斯工业平均指数比前一交易日上涨250.40点，收于51176.96点，涨幅为0.49%；标准普尔500种股票指数上涨56.27点，收于7722.72点，涨幅为0.73%；纳斯达克综合指数上涨319.27点，收于27190.86点，涨幅为1.19%。 板块方面，标普500指数十一大板块十涨一跌。非必需消费品板块和科技板块分别以1.38%和1.06%的涨幅领涨，医疗板块下跌0.04%。"
