    "author": "洪泽华",
    "description": "新华社阿布贾10月2日电（记者洪泽华）尼日利亚东北部博尔诺州政府2日说，该州马尔泰地方政府区日前发现15具遗体，疑为“博科圣地”极端组织发动袭击所致。 博尔诺州政府发言人说，袭击发生在9月30日，死者经辨认是当地农民。这些农民在丛林采集柴火时，疑似遭到“博科圣地”极端组织伏击。 据尼日利亚《抨击报》报道，事发当日共有18名农民前往农场工作，目前仍有3人下落不明。",
    "content": "新华社阿布贾10月2日电（记者洪泽华）尼日利亚东北部博尔诺州政府2日说，该州马尔泰地方政府区日前发现15具遗体，疑为“博科圣地”极端组织发动袭击所致。 博尔诺州政府发言人说，袭击发生在9月30日，死者经辨认是当地农民。这些农民在丛林采集柴火时，疑似遭到“博科圣地”极端组织伏击。 据尼日利亚《抨击报》报道，事发当日共有18名农民前往农场工作，目前仍有3人下落不明。"
