    "author": "江宥林",
    "description": "新华社基辅10月2日电 乌克兰哈尔科夫市市长捷列霍夫2日在社交媒体发布消息说，该市当天遭遇俄军袭击，已造成两人死亡、31人受伤，伤者包括两名儿童。 捷列霍夫2日早些时候援引乌有关部门消息说，俄军当天用校正航空炸弹对哈尔科夫市2个区发动袭击，其中一枚炸弹击中一处居民楼，造成人员受伤。",
    "content": "新华社基辅10月2日电 乌克兰哈尔科夫市市长捷列霍夫2日在社交媒体发布消息说，该市当天遭遇俄军袭击，已造成两人死亡、31人受伤，伤者包括两名儿童。 捷列霍夫2日早些时候援引乌有关部门消息说，俄军当天用校正航空炸弹对哈尔科夫市2个区发动袭击，其中一枚炸弹击中一处居民楼，造成人员受伤。"
