    "content": "10月2日，安保人员在巴西首都巴西利亚的美国驻巴西大使馆外警戒。新华社发（卢西奥·塔沃拉摄） 新华社巴西利亚10月2日电（记者吴昊 杨家和）美国驻巴西使领馆2日因“安全问题”暂停线下领事服务。澳大利亚驻巴西大使馆同日因“安全问题”关闭。 据美国驻巴西大使馆1日晚发布的公告，需要紧急协助的美国公民在此期间不要前往美国驻巴西大使馆、领事馆或其他驻巴西外交机构。 10月2日，安保人员在巴西首都巴西利亚的美国驻巴西大使馆外警戒。新华社发（卢西奥·塔沃拉摄） 巴西媒体援引美国驻圣保罗领事馆一名工作人员的话报道，该领事馆已暂停…"
