    "content": "新华社耶路撒冷10月2日电（记者陈君清 冯国芮）以色列总理内塔尼亚胡2日发表视频声明说，迪拜航空公司客机驾驶舱冲突的“真相逐渐明朗”，并称袭击者受到极端思想影响，意图让客机坠毁。 内塔尼亚胡还说，以方正在调查袭击者是否“受他人指使”，无论幕后黑手是谁，都将“付出沉重代价”。 伊朗国家电视台1日援引消息人士的话报道，此次驾驶舱冲突事件是一次针对伊朗的“假旗行动”。 9月30日，迪拜航空FZ1073航班从阿联酋迪拜飞往以色列特拉维夫途中发生安全事件。据阿联酋媒体报道，该航班副驾驶涉嫌在驾驶舱内刺伤机长，导致客机突然急降…"
