    "content": "这是10月2日在香港拍摄的庆祝中华人民共和国成立77周年无人机汇演现场。新华社发 新华社香港10月2日电（记者贺小童）由紫荆文化集团主办、紫荆杂志社承办的庆祝中华人民共和国成立77周年无人机汇演2日在香港红磡新海滨举行。 21时30分许，2000余架无人机腾空而起，点亮夜空。绚烂夜空下，金色数字“77”率先在维港上空汇聚成形，伴随灵动飞舞的彩带，拉开汇演序幕。 历时15分钟的汇演中，十余幕篇章传递着香港与祖国血脉相连的深厚情谊。变幻的无人机方阵时而化作运载火箭，时而变为高铁动车组，展现“中国速度”的蓬勃活力。 这是…"
