    "description": "新华社香港10月2日电（谢妞）第十届环球大湾区高峰论坛2日在香港举行。论坛以“乘势而上·智建未来”为主题，多位政商学界嘉宾围绕北部都会区发展、粤港澳大湾区融入全球经济链等议题展开讨论。 香港特区行政长官李家超视频致辞表示，香港会持续推进粤港澳大湾区协同发展，加强科技创新合作、促进基础设施“硬联通”、深化规则衔接和机制对接“软联通”、实现粤港澳居民“心联通”。此外，特区政府将全力发展绿色金融和绿色科技，与粤港澳大湾区城市共同推动低碳转型，…",
    "content": "新华社香港10月2日电（谢妞）第十届环球大湾区高峰论坛2日在香港举行。论坛以“乘势而上·智建未来”为主题，多位政商学界嘉宾围绕北部都会区发展、粤港澳大湾区融入全球经济链等议题展开讨论。 香港特区行政长官李家超视频致辞表示，香港会持续推进粤港澳大湾区协同发展，加强科技创新合作、促进基础设施“硬联通”、深化规则衔接和机制对接“软联通”、实现粤港澳居民“心联通”。此外，特区政府将全力发展绿色金融和绿色科技，与粤港澳大湾区城市共同推动低碳转型，为国家实现“双碳”目标贡献湾区力量，为粤港澳大湾区开拓经济可持续发展的新动能。 …"
