    "description": "西藏山南市措美80兆瓦风电项目首台机组10月2日顺利并网发电。这一项目全面投产后，预计年均节约标准煤5.59万吨，减少二氧化碳排放15.34万吨。 措美80兆瓦风电项目位于山南市措美县哲古镇，场址平均海拔5150米，安装了13台单机容量6.25兆瓦风力发电机组，配套16兆瓦/64兆瓦时构网型储能系统。新建的一座220千伏升压站，是目前世界海拔较高的风电项目配套升压站。作为西藏保障性并网新能源重点项目之一，这一项目是西藏首个全部采用200…",
    "content": "西藏山南市措美80兆瓦风电项目首台机组10月2日顺利并网发电。这一项目全面投产后，预计年均节约标准煤5.59万吨，减少二氧化碳排放15.34万吨。 措美80兆瓦风电项目位于山南市措美县哲古镇，场址平均海拔5150米，安装了13台单机容量6.25兆瓦风力发电机组，配套16兆瓦/64兆瓦时构网型储能系统。新建的一座220千伏升压站，是目前世界海拔较高的风电项目配套升压站。作为西藏保障性并网新能源重点项目之一，这一项目是西藏首个全部采用200型6.25兆瓦风机的风电项目。 西藏措美80兆瓦风电项目风机远景。（华电新能源集…"
