    "content": "新华社日本名古屋10月2日电（记者王恒志）爱知·名古屋亚运会3日进入尾声，除马术外所有项目将收官。当日决出47枚金牌，吴易昺出战网球男单决赛，冲击一张洛杉矶奥运会门票；男足亚运队将在铜牌赛中迎战乌兹别克斯坦队。 第三次参加亚运会的吴易昺将在决赛中面对老对手黄泽林。三年前的杭州亚运会，正是这名中国香港队选手将吴易昺挡在八强之外。这也是26岁的吴易昺第二次打进亚运决赛，2018年雅加达亚运会，初出茅庐的他遭遇逆转，获得一枚银牌。由于亚运单打冠军将获得一张洛杉矶奥运会门票，吴易昺势必全力以赴。 10月2日，吴易昺在男单半…"
