    "author": "陈怡,孙一然",
    "description": "新华社首尔10月2日电（记者陈怡 孙一然）据韩联社2日报道，韩国统一部长官郑东泳当天提议韩国和朝鲜见面沟通围绕军事分界线的分歧。 郑东泳当天表示，近期发生的非军事区地雷爆炸事故的核心原因在于军事分界线分歧。“韩国、朝鲜以及‘联合国军司令部’测定的界线都不一样。如果不解决这个问题，同样的事故随时可能再次发生。” 郑东泳表示，作为统一部长官，他向朝方提议应见面沟通，至少应就军事分界线测定和确认事宜进行沟通。 根据朝鲜战争停战协定，双方把实际…",
    "content": "新华社首尔10月2日电（记者陈怡 孙一然）据韩联社2日报道，韩国统一部长官郑东泳当天提议韩国和朝鲜见面沟通围绕军事分界线的分歧。 郑东泳当天表示，近期发生的非军事区地雷爆炸事故的核心原因在于军事分界线分歧。“韩国、朝鲜以及‘联合国军司令部’测定的界线都不一样。如果不解决这个问题，同样的事故随时可能再次发生。” 郑东泳表示，作为统一部长官，他向朝方提议应见面沟通，至少应就军事分界线测定和确认事宜进行沟通。 根据朝鲜战争停战协定，双方把实际控制线作为军事分界线。军事分界线东西长240公里，南北两侧各两公里以内为非军事区…"
