    "content": "新华社日本名古屋10月2日电（记者王沁鸥、肖世尧）国庆节当晚，19岁的储守宏为中国队拼下爱知·名古屋亚运会男子速度攀岩金牌，这是中国队在亚运会上首枚速度个人项目金牌。 10月1日，储守宏在比赛后庆祝。新华社记者 贾宇辰 摄 夺冠后，储守宏异常兴奋，在空中对着全场高喊“I'm from China!（我来自中国）”。但落地后，他又抑制不住翻涌的情绪，在岩壁一侧观众看不到的地方，抱住主教练钟齐鑫，失声痛哭。 眼泪背后，有怎样的故事？ 10月1日，储守宏（左）与教练在比赛后。新华社记者 王沁鸥 摄 “那段时间，我都不想比…"
