    "description": "新华社北京10月2日电 人民日报10月3日评论员文章：为新中国取得的举世瞩目成就无比自豪——论学习贯彻习近平总书记在庆祝中华人民共和国成立77周年招待会上重要讲话 “我们为新中国取得的举世瞩目成就无比自豪，对中国式现代化的光明前景充满信心。” 习近平总书记在庆祝中华人民共和国成立77周年招待会上发表重要讲话，总结辉煌成就、展望美好未来，鼓舞全党全国各族人民坚定信心、振奋精神，把强国建设、民族复兴伟业不断推向前进。 77年来，党团结带领人…",
    "content": "新华社北京10月2日电 人民日报10月3日评论员文章：为新中国取得的举世瞩目成就无比自豪——论学习贯彻习近平总书记在庆祝中华人民共和国成立77周年招待会上重要讲话 “我们为新中国取得的举世瞩目成就无比自豪，对中国式现代化的光明前景充满信心。” 习近平总书记在庆祝中华人民共和国成立77周年招待会上发表重要讲话，总结辉煌成就、展望美好未来，鼓舞全党全国各族人民坚定信心、振奋精神，把强国建设、民族复兴伟业不断推向前进。 77年来，党团结带领人民不懈奋斗，创造了经济快速发展和社会长期稳定两大奇迹，书写了中华民族几千年历史上…"
