    "description": "新华社香港/澳门10月2日电（张雅诗、齐菲）香港特区政府、澳门特区政府近日分别举行分享会，多名参与“向国旗敬礼”主题活动的港澳学生分享此行中的学习成果。 10月2日在九龙工业学校举行的分享会上，参与“向国旗敬礼”主题活动的香港大中小学学生代表，分享了访京期间的见闻和体会。 香港教育大学学生王诗雯表示，一面国旗对我们来说有了新的意义。每一次升旗都凝聚了国家的精神，也是一堂无声的国民教育课，提醒我们要承担责任。 培侨中学升旗队成员张贝涵表示…",
    "content": "新华社香港/澳门10月2日电（张雅诗、齐菲）香港特区政府、澳门特区政府近日分别举行分享会，多名参与“向国旗敬礼”主题活动的港澳学生分享此行中的学习成果。 10月2日在九龙工业学校举行的分享会上，参与“向国旗敬礼”主题活动的香港大中小学学生代表，分享了访京期间的见闻和体会。 香港教育大学学生王诗雯表示，一面国旗对我们来说有了新的意义。每一次升旗都凝聚了国家的精神，也是一堂无声的国民教育课，提醒我们要承担责任。 培侨中学升旗队成员张贝涵表示，这次活动让他切实体会到国家的发展历程，以及一代代人奋发前行的努力。清晨在天安门…"
