    "author": "任耀庭",
    "description": "新华社罗马10月2日电（记者任耀庭）联合国粮食及农业组织（粮农组织）2日发布报告说，受物流运输受阻和天气风险等因素影响，9月粮农组织食品价格指数升至近四年来最高水平。 数据显示，9月粮农组织食品价格指数平均为136.0点，较修订后的8月指数134.0点上涨1.5%，为2022年11月以来最高水平。谷物、食糖和植物油价格指数均有所上涨，肉类和乳制品价格指数则出现下降。 粮农组织首席经济学家马克西莫·托雷罗说，霍尔木兹海峡和黑海航运受阻加上…",
    "content": "新华社罗马10月2日电（记者任耀庭）联合国粮食及农业组织（粮农组织）2日发布报告说，受物流运输受阻和天气风险等因素影响，9月粮农组织食品价格指数升至近四年来最高水平。 数据显示，9月粮农组织食品价格指数平均为136.0点，较修订后的8月指数134.0点上涨1.5%，为2022年11月以来最高水平。谷物、食糖和植物油价格指数均有所上涨，肉类和乳制品价格指数则出现下降。 粮农组织首席经济学家马克西莫·托雷罗说，霍尔木兹海峡和黑海航运受阻加上气候冲击，正推动全球大宗商品价格持续上涨，并给能源、运输和食品价格带来压力。如果…"
