    "content": "新华社日本名古屋10月2日电（记者张粲）爱知·名古屋亚运会摔跤比赛2日继续进行，中国选手佈和额尔敦获得男子自由式125公斤级银牌，冯紫琪、李文吉分别获得女子自由式50公斤级和76公斤级铜牌。 10月2日，中国选手佈和额尔敦（右）在决赛中。新华社记者 龙雷 摄 在男子自由式125公斤级比赛中，佈和额尔敦前两轮强势晋级。半决赛面对巴林选手沙里波夫，他一度以4:7落后，但在关键时刻抓住机会完成压制，逆转晋级决赛。 决赛中，佈和额尔敦迎战伊朗名将扎雷。这名伊朗选手是巴黎奥运会银牌得主，并曾三次获得世锦赛冠军。比赛中，扎雷首…"
