    "content": "10月2日，在“跟着功夫游大陆”主题推介活动现场，高雄餐旅大学的同学们在“功夫门”前合影留念。新华社记者 马欣然 摄 新华社台北10月2日电（记者马欣然、黄扬）2026高雄冬季旅展2日在高雄展览馆开幕，“跟着功夫游大陆”主题推介活动在此间亮相。 本次推介由海峡两岸旅游交流协会高雄办事分处联合河南、湖北、四川、广东四省文旅部门共同推出。活动以四大功夫流派为脉络，融合武术文化、非遗技艺、文创产品与旅游资源，让台湾同胞循着功夫足迹，沉浸式领略大陆山河之美。 展区入口处，“功夫门”打卡点人气颇高。山门、翠竹、大熊猫与咏春木…"
