    "author": "朱昊晨,徐谦",
    "description": "新华社赫尔辛基10月2日电（记者朱昊晨 徐谦）斯德哥尔摩消息：瑞典议会议长安德烈亚斯·诺伦2日再次授权社会民主党党首、前首相玛格达莱娜·安德松尝试组建新政府。 诺伦当天在新闻发布会上表示，此前围绕议长选举出现的情况促使安德松交回尝试组建新政府的任务，但议会席位分布仍是决定由谁负责尝试组阁的基础，因此决定再次将该任务交给安德松。 诺伦表示，新的尝试组阁任务将于10月5日正式开始，安德松应于10月12日前报告相关进展。如组阁谈判磋商需要更多…",
    "content": "新华社赫尔辛基10月2日电（记者朱昊晨 徐谦）斯德哥尔摩消息：瑞典议会议长安德烈亚斯·诺伦2日再次授权社会民主党党首、前首相玛格达莱娜·安德松尝试组建新政府。 诺伦当天在新闻发布会上表示，此前围绕议长选举出现的情况促使安德松交回尝试组建新政府的任务，但议会席位分布仍是决定由谁负责尝试组阁的基础，因此决定再次将该任务交给安德松。 诺伦表示，新的尝试组阁任务将于10月5日正式开始，安德松应于10月12日前报告相关进展。如组阁谈判磋商需要更多时间，安德松可以申请延长期限。 安德松随后在社交媒体上发文表示，她将考虑如何推进…"
