    "author": "王一帆",
    "description": "新华社北京10月2日电 以色列航空公司2日宣布，因未获得阿联酋方面的降落许可，该公司两趟原定飞往迪拜接回滞留以色列旅客的航班已被取消。 9月30日，阿联酋迪拜航空从迪拜飞往特拉维夫的一架航班在飞行途中发生驾驶舱冲突事件。随后，迪拜航空宣布暂停所有往返以色列的航班，等待事件调查。据以色列媒体报道，受此事影响，有逾1万名以色列旅客滞留在迪拜等地。 9月30日，一架载有迪拜航空涉事航班乘客的替代航班降落在以色列特拉维夫的本-古里安国际机场。新…",
    "content": "新华社北京10月2日电 以色列航空公司2日宣布，因未获得阿联酋方面的降落许可，该公司两趟原定飞往迪拜接回滞留以色列旅客的航班已被取消。 9月30日，阿联酋迪拜航空从迪拜飞往特拉维夫的一架航班在飞行途中发生驾驶舱冲突事件。随后，迪拜航空宣布暂停所有往返以色列的航班，等待事件调查。据以色列媒体报道，受此事影响，有逾1万名以色列旅客滞留在迪拜等地。 9月30日，一架载有迪拜航空涉事航班乘客的替代航班降落在以色列特拉维夫的本-古里安国际机场。新华社发（吉尔·科恩·马根摄） 以色列航空1日晚宣布将于2日运营这两架航班。根据原…"
