    "title": "迪拜航空机长讲述驾驶舱惊魂一刻",
    "link": "http://www.news.cn/20261002/ea0b769429e44707ac42bdf29c63c40c/c.html",
    "pub_date": "2026-10-02 20:30:23",
    "author": "王宏彬",
    "description": "新华社北京10月2日电 印度籍机长斯米特·马奇切尔9月30日执飞迪拜航空公司一架客机时，被他的副手刺伤，倒在血泊中。危急关头，马奇切尔用尽最后一丝力气，打开驾驶舱门，让乘客和机组人员得以进入，制伏据称试图制造坠机事件的副驾驶，挽救了机上180多人的性命。马奇切尔10月2日在医院和印度总理莫迪通视频电话，讲述了驾驶舱惊魂一刻。 视频中，马奇切尔躺在阿联酋阿布扎比一家医院的病床上，戴着鼻氧管，头上缠着绷带。他一边讲，一边抹眼泪，难掩激动情绪…",
    "content": "新华社北京10月2日电 印度籍机长斯米特·马奇切尔9月30日执飞迪拜航空公司一架客机时，被他的副手刺伤，倒在血泊中。危急关头，马奇切尔用尽最后一丝力气，打开驾驶舱门，让乘客和机组人员得以进入，制伏据称试图制造坠机事件的副驾驶，挽救了机上180多人的性命。马奇切尔10月2日在医院和印度总理莫迪通视频电话，讲述了驾驶舱惊魂一刻。 视频中，马奇切尔躺在阿联酋阿布扎比一家医院的病床上，戴着鼻氧管，头上缠着绷带。他一边讲，一边抹眼泪，难掩激动情绪。他被副驾驶刺伤倒地后，立刻觉察到飞机急速下坠。据媒体报道，当时客机巡航高度在约…"
