    "content": "新华社太原10月2日电 题：山西：“赛事游”成外国人深度体验中国新潮流 新华社记者刘扬涛、陈志豪 “跑步是形式，更重要的目的是旅行。”参加完9月27日在山西太原举办的2026太原马拉松后，52岁的日本跑步爱好者合泉日实子说。 合泉日实子是北京一家企业的员工，工作之余参加中国各地举办的马拉松赛事是她的爱好之一。“9月初我刚参加了包头马拉松，10月我还要参加天津马拉松。原本北京马拉松我也想去的，可惜没有摇到号。”她表示，通过比赛的方式，她已经去过不少地方旅行。 图为合泉日实子在2026太原马拉松现场 随着中秋国庆假期来…"
